    program = tuple(program)
    if sum(ins.op == "WG.BEGIN" for ins in program) <= 1:
        return
queues, tape_ids, owners, edges, indegree, commit_before = _graph(program, queues)
ready = deque(pc for pc, degree in enumerate(indegree) if degree == 0)

